<div class="d-flex justify-content-between align-items-center mb-4 flex-wrap gap-2"><div><h3>المالية والمدفوعات</h3><div class="text-muted">العميل يدفع عبر منصة مِهَن، والمنصة تحتسب عمولتها ثم تعرض مستحقاتك والتحويلات.</div></div><a class="btn btn-outline-primary" href="<?= url('/provider/finance/export') ?>">تصدير CSV</a></div><div class="row g-3 mb-4"><?php foreach([['إجمالي الفواتير',$stats['gross'],'primary'],['المحصّل عبر المنصة',$stats['collected'],'success'],['عمولة المنصة',$stats['commission_on_collected'],'danger'],['صافي مستحقك',$stats['provider_net_collected'],'info'],['تم تحويله لك',$stats['paid_out'],'success'],['متاح للتحويل',$stats['available_payout'],'warning']] as $c): ?><div class="col-6 col-xl-2"><div class="card p-3 h-100"><div class="small text-muted"><?= e($c[0]) ?></div><div class="fs-5 fw-bold text-<?= $c[2] ?>"><?= number_format((float)$c[1],2) ?> <?= e($currency) ?></div></div></div><?php endforeach; ?></div><div class="alert alert-info border">لا يوجد تسجيل دفع نقدي مباشر لمقدم الخدمة. كل دفعة يجب أن تسجل عبر منصة مِهَن.</div><div class="card p-3 mb-4"><h5>الفواتير</h5><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>الفاتورة</th><th>الطلب</th><th>العميل</th><th>قيمة الخدمة</th><th>العمولة</th><th>صافي المستحق</th><th>مدفوع</th><th>الحالة</th></tr></thead><tbody><?php foreach($invoices as $i): ?><tr><td><?= e($i['invoice_number']) ?></td><td><?= e($i['request_number']) ?></td><td><?= e($i['customer_name']) ?></td><td><?= number_format($i['total_amount'],2) ?></td><td><?= number_format($i['commission_amount'],2) ?></td><td><?= number_format($i['provider_net'],2) ?></td><td class="text-success"><?= number_format($i['amount_paid'],2) ?></td><td><?= statusBadge($i['payment_status']) ?></td></tr><?php endforeach; if(!$invoices): ?><tr><td colspan="8" class="text-center text-muted py-4">لا توجد فواتير.</td></tr><?php endif; ?></tbody></table></div></div><div class="card p-3"><h5>سجل التحويلات</h5><div class="table-responsive"><table class="table table-sm"><thead><tr><th>التاريخ</th><th>الفاتورة</th><th>المبلغ</th><th>المرجع</th><th>الحالة</th></tr></thead><tbody><?php foreach($payouts as $p): ?><tr><td><?= e($p['paid_at']) ?></td><td><?= e($p['invoice_number']) ?></td><td><?= number_format($p['amount'],2) ?> <?= e($currency) ?></td><td><?= e($p['reference']??'—') ?></td><td><?= statusBadge($p['status']) ?></td></tr><?php endforeach; if(!$payouts): ?><tr><td colspan="5" class="text-center text-muted">لا توجد تحويلات مسجلة بعد.</td></tr><?php endif; ?></tbody></table></div></div>